import csv, math

# load data
xs=[]; ys=[]
with open('/app/spectrum.csv', newline='') as f:
    r=csv.reader(f); next(r)
    for row in r:
        xs.append(float(row[0])); ys.append(float(row[1]))

windows = {
    'D':  (1250.0, 1450.0),
    'G':  (1530.0, 1650.0),
    '2D': (2600.0, 2770.0),
}

def model(x, p):
    x0, logg, A, B = p
    g = math.exp(logg)
    return A * g*g / ((x-x0)*(x-x0) + g*g) + B

def residuals(x, y, p):
    return [yy - model(xx, p) for xx, yy in zip(x, y)]

def chi2(x, y, p):
    return sum(r*r for r in residuals(x, y, p))

def solve_linear(A, b):
    n = len(b)
    M = [A[i][:] + [b[i]] for i in range(n)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col]) < 1e-300:
            raise ValueError('singular matrix')
        M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        for j in range(col, n+1):
            M[col][j] /= pv
        for i in range(n):
            if i != col and abs(M[i][col]) > 1e-300:
                fac = M[i][col]
                for j in range(col, n+1):
                    M[i][j] -= fac * M[col][j]
    return [M[i][n] for i in range(n)]

def jacobian(x, y, p):
    # residual derivative J_ij = dr_i/dp_j, numerical central differences
    m = len(x); n = len(p)
    J = [[0.0]*n for _ in range(m)]
    steps = [1e-5, 1e-6, 1e-6, 1e-6]
    for j in range(n):
        h = steps[j]
        pp = p[:]; pm = p[:]
        pp[j] += h; pm[j] -= h
        for i in range(m):
            J[i][j] = ((y[i] - model(x[i], pp)) - (y[i] - model(x[i], pm))) / (2*h)
    return J

def fit_peak(name, lo, hi):
    inds = [i for i,xv in enumerate(xs) if lo <= xv <= hi]
    x = [xs[i] for i in inds]
    y = [ys[i] for i in inds]
    imax = max(range(len(y)), key=lambda i: y[i])
    baseline = min(y)
    # initial gamma estimate via half-max crossings around peak
    ymax = y[imax]
    half = baseline + 0.5*(ymax-baseline)
    left = imax
    while left > 0 and y[left] > half:
        left -= 1
    right = imax
    while right < len(y)-1 and y[right] > half:
        right += 1
    if right > left and x[right] > x[left]:
        fwhm = x[right]-x[left]
        g0 = max(1.0, fwhm/2.0)
    else:
        g0 = 20.0
    p = [x[imax], math.log(g0), ymax-baseline, baseline]
    lam = 1e-3
    old = chi2(x, y, p)
    for it in range(300):
        J = jacobian(x, y, p)
        r = residuals(x, y, p)
        n = len(p)
        JTJ = [[sum(J[k][i]*J[k][j] for k in range(len(x))) for j in range(n)] for i in range(n)]
        g = [sum(J[k][i]*r[k] for k in range(len(x))) for i in range(n)]
        improved = False
        for attempt in range(30):
            M = [row[:] for row in JTJ]
            for i in range(n):
                M[i][i] *= (1.0 + lam)
            try:
                delta = solve_linear(M, g)
            except Exception:
                lam *= 10.0; continue
            pnew = [p[i] + delta[i] for i in range(n)]
            new = chi2(x, y, pnew)
            if new < old:
                p = pnew
                old = new
                lam = max(1e-12, lam*0.3)
                improved = True
                break
            else:
                lam *= 3.0
        if not improved:
            break
        if max(abs(d) for d in delta) < 1e-10:
            break
    x0, logg, A, B = p
    g = math.exp(logg)
    rms = math.sqrt(old/len(x))
    print(name, 'n=', len(x), 'x0=', x0, 'gamma=', g, 'amp=', A, 'offset=', B, 'chi2=', old, 'rms=', rms, 'iters=', it)
    return {'x0':x0, 'gamma':g, 'amplitude':A, 'offset':B}, old, len(x)

for name,(lo,hi) in windows.items():
    fit_peak(name, lo, hi)
